Code.Terraform:
```hcl
resource "cloudflare_ruleset" "custom" {
  zone_id = "<ZONE_ID>"
  name    = "custom rules"
  kind    = "zone"
  phase   = "http_request_firewall_custom"

  rules = [{
    action = "skip"
    # Critical: scope the skip to trusted traffic instead of "true"
    expression = "(ip.src in $trusted_monitoring and http.request.uri.path eq \"/health\")"
    action_parameters = { ruleset = "current" }
  }]
}
```
